INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Prüfung 1: Planen eines Softwareprodukts > Datenschutz > Grundsätze (Art. 5) > Datenminimierung
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Fordert der Grundsatz der Datenminimierung gemäß Art. 5 DSGVO, dass nur die für den Zweck notwendigen Daten verarbeitet werden?', 2, '[{"text": "Ja", "correct": true, "because": "Art. 5 Abs. 1c verlangt Minimierung auf das Erforderliche"}, {"text": "Nein", "correct": false, "because": "Datenminimierung ist zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann die Verarbeitung von mehr Daten als nötig den Grundsatz der Datenminimierung verletzen?', 2, '[{"text": "Ja", "correct": true, "because": "Überflüssige Datenverarbeitung widerspricht Art. 5"}, {"text": "Nein", "correct": false, "because": "Minimierung wird verletzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss die Datenminimierung immer durch technische Maßnahmen wie Verschlüsselung umgesetzt werden?', 2, '[{"text": "Nein", "correct": true, "because": "Minimierung bezieht sich auf Menge, nicht nur Technik"}, {"text": "Ja", "correct": false, "because": "Technik ist Mittel, nicht Pflicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Unternehmen bei Nichteinhaltung der Datenminimierung mit Sanktionen rechnen?', 2, '[{"text": "Ja", "correct": true, "because": "Verstöße gegen Art. 5 können Bußgelder nach sich ziehen"}, {"text": "Nein", "correct": false, "because": "Sanktionen sind möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Datenminimierung nur für personenbezogene Daten relevant?', 2, '[{"text": "Ja", "correct": true, "because": "Art. 5 gilt für personenbezogene Daten"}, {"text": "Nein", "correct": false, "because": "Nicht auf andere Daten anwendbar"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolgt der Grundsatz der Datenminimierung gemäß Art. 5 DSGVO?', 2, '[{"text": "Reduzierung der verarbeiteten Datenmenge", "correct": true, "because": "Nur notwendige Daten erheben"}, {"text": "Maximierung der Datenspeicherung", "correct": false, "because": "Widerspricht Minimierung"}, {"text": "Erhöhung der Verarbeitungsgeschwindigkeit", "correct": false, "because": "Kein Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Anforderung beschreibt die Datenminimierung am besten?', 3, '[{"text": "Nur zweckgebundene Daten erheben", "correct": true, "because": "Art. 5 Abs. 1c fordert Zweckmäßigkeit"}, {"text": "Alle verfügbaren Daten sammeln", "correct": false, "because": "Widerspricht Minimierung"}, {"text": "Daten unbegrenzt speichern", "correct": false, "because": "Verboten"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahme unterstützt die Datenminimierung am effektivsten?', 2, '[{"text": "Daten nur für festgelegte Zwecke erheben", "correct": true, "because": "Begrenzt Datenmenge"}, {"text": "Maximale Datenerhebung", "correct": false, "because": "Widerspricht Minimierung"}, {"text": "Schnelle Datenverarbeitung", "correct": false, "because": "Kein Minimierungsaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Beispiel verstößt gegen den Grundsatz der Datenminimierung?', 2, '[{"text": "Erhebung von Geburtsdaten für Marketing ohne Zweck", "correct": true, "because": "Unnötige Daten"}, {"text": "Erhebung von Namen für Vertragsabschluss", "correct": false, "because": "Zweckgebunden"}, {"text": "Speicherung von Adressen für Lieferung", "correct": false, "because": "Notwendig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Konsequenz droht bei Verstoß gegen die Datenminimierung?', 2, '[{"text": "Bußgelder", "correct": true, "because": "Verstöße gegen Art. 5 strafbar"}, {"text": "Systemausfall", "correct": false, "because": "Kein direkter Effekt"}, {"text": "Geringere Nutzerfreundlichkeit", "correct": false, "because": "Nicht relevant"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte umfasst der Grundsatz der Datenminimierung nach Art. 5 DSGVO?', 4, '[{"text": "Angemessenheit", "correct": true, "because": "Daten müssen zweckmäßig sein"}, {"text": "Erforderlichkeit", "correct": true, "because": "Nur notwendige Daten"}, {"text": "Zweckbezogenheit", "correct": true, "because": "Daten auf Zweck beschränken"}, {"text": "Maximale Erhebung", "correct": false, "because": "Widerspricht Minimierung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahmen fördern die Datenminimierung?', 3, '[{"text": "Erhebung nur notwendiger Daten", "correct": true, "because": "Reduziert Datenmenge"}, {"text": "Pseudonymisierung", "correct": true, "because": "Verringert Identifizierbarkeit"}, {"text": "Datenschutzfreundliche Voreinstellungen", "correct": true, "because": "Minimiert Standarddaten"}, {"text": "Unbegrenzte Speicherung", "correct": false, "because": "Verboten"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Daten sollten gemäß Datenminimierung nicht erhoben werden?', 4, '[{"text": "Geburtsdaten ohne Zweck", "correct": true, "because": "Nicht erforderlich"}, {"text": "Hobbys für Marketing ohne Grund", "correct": true, "because": "Überflüssig"}, {"text": "E-Mail für Newsletter ohne Einwilligung", "correct": true, "because": "Nicht rechtmäßig"}, {"text": "Name für Vertrag", "correct": false, "because": "Zweckgebunden"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Folgen kann ein Verstoß gegen die Datenminimierung haben?', 3, '[{"text": "Bußgelder", "correct": true, "because": "Bis zu 20 Mio. Euro möglich"}, {"text": "Schadensersatzansprüche", "correct": true, "because": "Betroffene können klagen"}, {"text": "Verarbeitungsverbot", "correct": true, "because": "Schwere Fälle"}, {"text": "Schnellere Verarbeitung", "correct": false, "because": "Keine Folge"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Prinzipien der DSGVO ergänzen die Datenminimierung?', 3, '[{"text": "Zweckbindung", "correct": true, "because": "Daten nur für festgelegte Zwecke"}, {"text": "Rechtmäßigkeit", "correct": true, "because": "Verarbeitung muss legal sein"}, {"text": "Speicherbegrenzung", "correct": true, "because": "Daten nur so lange wie nötig"}, {"text": "Maximale Speicherung", "correct": false, "because": "Widerspricht Minimierung"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Datenminimierung fordert nur notwendige Daten. b) Verschlüsselung ist zwingend erforderlich.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Minimierung ja, Verschlüsselung nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Überflüssige Datenerhebung verstößt gegen Datenminimierung. b) Sie gilt nur für digitale Daten.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Verstoß ja, auch papierbasierte Daten"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Datenminimierung schützt die Privatsphäre. b) Bußgelder sind keine Folge von Verstößen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Privatsphäre ja, Bußgelder möglich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Pseudonymisierung unterstützt die Datenminimierung. b) Alle Daten müssen erhoben werden.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Pseudonymisierung ja, maximale Erhebung nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Zweckbindung ergänzt die Datenminimierung. b) Datenminimierung betrifft nur technische Daten.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Zweckbindung ja, nur personenbezogene Daten"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

